return {["fb205_01"]={["down"]=[[fb205_04]],["dsc"]=[[小镇中心以北的大街。街道两旁绿柳垂杨，车马人流来来往往，不少妇人手提竹篮，撑着油纸伞穿梭在街道中央。正值夏日，树上蝉鸣喧天，街边几个老汉抱着西瓜乘凉扇风，不时说笑一番。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_01]],["item1"]=[[changzhubaishe2]],["name"]=[[北大街]],["permission"]=2,["role1"]=[[changzhujumin6]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_47]]},["fb205_02"]={["down"]=[[fb205_07]],["dsc"]=[[这里是两条街交汇之处。顺着几层低矮的石阶往上走便可从此纵览整条街道的风光，旁侧屋舍林立，每每间隔十步就挂有一排红灯笼，又有小贩推着小车往前赶去，车轱辘碾着凹凸不平的石板，使得里头的货物发出清脆的碰撞声。两只黄狗正在前头跑来跑去，不时到水潭中打个滚。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_02]],["left"]=[[fb205_53]],["name"]=[[大街口]],["permission"]=2,["right"]=[[fb205_03]],["role1"]=[[changzhujumin19]],["stepMusic"]=[[jiaobu]]},["fb205_03"]={["dsc"]=[[北大街的内街。北内大街一侧的小亭新换了副对联，亭前翠绿色的木板上用漆墨题着“清风咏蝉”几个大字。亭内两个老者手执蒲扇，眼前棋局胜劣分明，楚河汉界已少有兵卒，几个年轻的后生站在周围欲言又止，神情专注，已然入局。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_03]],["item1"]=[[22xcfwscq8]],["left"]=[[fb205_02]],["name"]=[[北内大街]],["permission"]=2,["right"]=[[fb205_04]],["role1"]=[[changzhujumin8]],["stepMusic"]=[[jiaobu]]},["fb205_04"]={["down"]=[[fb205_08]],["dsc"]=[[四条北街的交汇之处。近日不知为何来了不少的船只，四面八方的人涌入平安小镇。未免码头拥挤，平日里运货的船只不得不匆忙卸货，十几个大汉搬着沉重的货物在人群中穿梭。旁边小贩挑着担子叫喊着，热腾腾的包子也刚刚出炉，引得几个孩童不肯离去。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_04]],["item1"]=[[changzhubaishe16]],["left"]=[[fb205_03]],["name"]=[[十字街口]],["permission"]=2,["right"]=[[fb205_05]],["role1"]=[[changzhujumin29]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_01]]},["fb205_05"]={["down"]=[[fb205_09]],["dsc"]=[[北大街的内街。北内大街一侧的小亭新换了副对联，亭前翠绿色的木板上用漆墨题着“清风咏蝉”几个大字。亭内两个老者手执蒲扇，眼前棋局胜劣分明，楚河汉界已少有兵卒，几个年轻的后生站在周围欲言又止，神情专注，已然入局。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_05]],["item1"]=[[22qxwp07]],["left"]=[[fb205_04]],["name"]=[[北内大街]],["permission"]=2,["right"]=[[fb205_06]],["role1"]=[[changzhujumin20]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_55]]},["fb205_06"]={["down"]=[[fb205_10]],["dsc"]=[[这里是两条街交汇之处。顺着几层低矮的石阶往上走便可从此纵览整条街道的风光，旁侧屋舍林立，每每间隔十步就挂有一排红灯笼，又有小贩推着小车往前赶去，车轱辘碾着凹凸不平的石板，使得里头的货物发出清脆的碰撞声。两只黄狗正在前头跑来跑去，不时到水潭中打个滚。]],["fightBackground"]=[