2]],["item1"]=[[changzhubaishe23]],["name"]=[[北大街]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb205_08]]},["fb205_13"]={["down"]=[[fb205_20]],["dsc"]=[[东大街的内街。一走入大街，跑堂的小厮就吆喝着来往的人群入店，一个头戴草帽的侠客坐在酒楼二楼的屋脊上俯瞰着整条大街的景况。两个不知道从哪里来的富家公子为争一坛美酒大打出手，仅隔着一条街，官府弟子正在缉拿浑水摸鱼的小偷。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_13]],["name"]=[[东内大街]],["permission"]=2,["role1"]=[[changzhujumin33a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_10]]},["fb205_14"]={["down"]=[[fb205_44]],["dsc"]=[[村道两侧开满野花，一个瘦弱的村民驾着驴车，拉着货物颠簸而来。驴上挂着的铜铃不断作响，回荡在山林中。几个手持锄头的农夫正在闲聊，因最近阴雨不断，他们的脚上都沾满了泥泞。夏日的炎热逼得他们戴起了草帽，脖子上也挂着一条条汗巾。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_14]],["item1"]=[[fbqztrigger04]],["name"]=[[小镇村口]],["permission"]=1,["stepMusic"]=[[jiaobu]]},["fb205_15"]={["down"]=[[fb205_48]],["dsc"]=[[这里是小镇的正大街。各色商铺大门敞开，首饰店聚满了从京城来的富人，这里虽说没什么金贵物件，但却能称得上“奇巧”二字。又因小镇多江湖人士，铁铺内新打了不少上好的兵刃，一旁的试刀石上已经砍痕累累。往前走数步，几个外商正谈论着中原的丝绸。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_15]],["item1"]=[[changzhubaishe14]],["left"]=[[fb205_44]],["name"]=[[平安大街]],["permission"]=1,["right"]=[[fb205_16]],["role1"]=[[changzhujumin26]],["role2"]=[[zhouhuodongsr]],["role3"]=[[zhouhuodongyr]],["role4"]=[[22liquansr01]],["stepMusic"]=[[jiaobu]]},["fb205_16"]={["dsc"]=[[中央广场西面的大街，往东便是中央广场。炎炎夏日，原本热闹的街道安静了不少，走在街上能听到人们来来往往的脚步声。几个村民提着水桶朝着水井走去，不多时从里面拉出了一盆蔬果，孩子们都围了上去。这是百姓夏日专门用于“冰镇”的法子，比不得高门大户的冰窖，却也能消暑自乐。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_16]],["left"]=[[fb205_15]],["name"]=[[平安西街]],["permission"]=1,["right"]=[[fb205_17]],["role1"]=[[changzhujumin5]],["role2"]=[[22fourwillowdh]],["role3"]=[[vote5npc01a]],["role4"]=[[25_1vote5npc01a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_11]]},["fb205_17"]={["down"]=[[fb205_23]],["dsc"]=[[中央广场西面的大街，往东便是中央广场。炎炎夏日，原本热闹的街道安静了不少，走在街上能听到人们来来往往的脚步声。几个村民提着水桶朝着水井走去，不多时从里面拉出了一盆蔬果，孩子们都围了上去。这是百姓夏日专门用于“冰镇”的法子，比不得高门大户的冰窖，却也能消暑自乐。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_17]],["item1"]=[[changzhubaishe18]],["left"]=[[fb205_16]],["name"]=[[平安西街]],["permission"]=1,["right"]=[[fb205_18]],["role1"]=[[changzhujumin25]],["role2"]=[[changzhujumin31]],["stepMusic"]=[[jiaobu]]},["fb205_18"]={["down"]=[[fb205_24]],["dsc"]=[[这里便是小镇的中心，小镇中最热闹的地方。广场上的老树成了村民和侠客们的乘凉佳地，头顶上蝉鸣喧天，也不知是谁在老树上绑了一个秋千，几个孩子相互推攮，嘻嘻哈哈好不热闹。一个捏糖人的老汉立在一侧擦着头上的汗水，一旁放着一个切开了的西瓜。挑担的村民慢慢的走着，相互讨论着最近村里的热闹事。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_18]],["item1"]=[[changzhubaishe4]],["item2"]=[[fbqztrigger01]],["left"]=[[fb205_17]],["name"]=[[中央广场]],["permission"]=1,["right"]=[[fb205_19]],["role1"]=[[changzhujumin16]],["role2"]=[[22qxnpc07a]],["role3"]=[[24votenpc03]],["role4"]=[[22zqhdmask]],["role5"]=[[25votenpc01a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_12]]},["fb205_19"]={["down"]=[[fb205_25]],["dsc"]=[[中央广场东面的大街，往西便是中央广场。街道两侧摆放着几个大水盆，里面装着刚刚从河里打捞上来的鲜鱼，不时溅起水花将买菜妇人的衣摆弄湿。一个邋遢道士手拿桃木剑，疯疯癫癫的立在肉铺前说着些听不懂的胡话。几个不知是何门何派的年轻弟子正好奇的朝着四周看来，似乎是第一次下山。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_19]],["item1"]=[[changzhubaishe15]],["left"]=[[fb205_18]],["name"]=[[平安东街]],["permission"]=1,["right"]=[[fb205_20]],["role1"]=[[changzhujumin15]],["role2"]=[[changzhujumin22]],["role3"]=[[21zonghengnpc]],["role4"]=[[zonghengnpc02]],["stepMusic"]=[[jiaobu]]},["fb205_20"]={["down"]=[[fb205_26]],["dsc"]=[[中央广场东面的大街，往西便是中央广场。街道两侧摆放着几个大水盆，里面装着刚刚从河里打捞上来的鲜鱼，不时溅起水花将买菜妇人的衣摆弄湿。一个邋遢道士手拿桃木剑，疯疯癫癫的立在肉铺前说着些听不懂的胡话。几个不知是何门何派的年轻弟子正好奇的朝着四周看来，似乎是第一次下山。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_20]],["item1"]=[[changzhubaishe30]],["item2"]=[[fbqztrigger03]],["left"]=[[fb205_19]],["name"]=[[平安东街]],["permission"]=1,["right"]=[[fb205_21]],["role1"]=[[changzhujumin32a]],["role2"]=[[25_1vote5npc02a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_13]]},["fb205_21"]={["dsc"]=[[浮云寺的大门，门上有金字写就的牌匾。不知打哪儿来的算卦道士在附近摆了一个摊位，倒是灿若莲花的说了不少吉利话，门口接引来客的两个小沙弥玩性未脱，一边假装扫地一边又往那处凑去，说说笑笑。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_21]],["left"]=[[fb205_20]],["name"]=[[浮云寺门]],["permission"]=2,["right"]=[[fb205_22]],["role1"]=[[changzhujumin11]],["role2"]=[[22fukumerchant]],["role3"]=[[24votenpc01a]],["stepMusic"]=[[jiaobu]]},["fb205_22"]={["dsc"]=[[浮云寺寺内。正中是一尊金色的大佛，周围供奉着十八罗汉。香客在这里上香祈福，香案上已经插满了香烛，僧人只好把旧的香烛取下，换上新香客的香烛。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_22]],["item1"]=[[22qxwp04]],["left"]=[[fb205_21]],["name"]=[[寺内]],["permission"]=2,["right"]=[[fb205_32]],["role1"]=[[znqlr1]],["role2"]=[[znqlr2]],["role3"]=[[22djbusinessman]],["role4"]=[[22qxnpc05a]],["role5"]=[[vote5npc03a]],["stepMusic"]=[[jiaobu]]},["fb205_23"]={["dsc"]=[[这是一间甚是简陋的铁匠铺，门上挂着个大铁砧，店内放着各式样的武器，墙上挂着几张犁头。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_23]],["item1"]=[[changzhubaishe19]],["name"]=[[铁匠铺]],["permission"]=2,["role1"]=[[22qxnpc08a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_17]]},["fb205_24"]={["down"]=[[fb205_27]],["dsc"]=[[中央广场南面的大街，往北便是中央广场。果农们吆喝贩卖着干果，不时相互闲聊几句今年种下的果种。几个孩童也不知是从哪里寻了一个破窑罐，找了一把枯木枝，有模有样的投起壶来。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_24]],["name"]=[[平安南街]],["permission"]=1,["role1"]=[[changzhujumin34a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_18]]},["fb205_25"]={["dsc"]=[[戏团最近新上了几幕新戏，说的是江湖豪杰、正邪相争，引得不少孩童和江湖人士围聚，热闹非凡。周边贩卖糕点瓜果的小贩自然不会错过这个机会，早早就备好一切，等着看戏之人到来。戏班的两个学徒正从戏台后的帷幕中探出头来，指着台下看戏的各色人群嬉笑打闹，自是一派天真无邪。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_25]],["item1"]=[[22qxwp03]],["name"]=[[庙会戏台]],["permission"]=2,["role1"]=[[changzhujumin3]],["role2"]=[[changzhujumin35a]],["roomBgm"]=[[chalou]],["roomBgmRule"]=1,["spfb203_ceTime"]=0,["stepMusic"]=[[jiaobu]],["up"]=[[fb205_19]]},["fb205_26"]={["dsc"]=[[这里是比武的擂台。擂台上缚着红色的绸带，两侧立有木牌，写着擂主与打擂之人的名号。一桌赌席开在左侧，又有庄家吆喝着买定离手。几个江湖草莽蓄势待发，正松快着筋骨准备走上擂台。]],["fightBackground"]=[[擂台]],["id"]=[[fb205_26]],["name"]=[[比武台]],["permission"]=2,["role1"]=[[51npc02o]],["role2"]=[[22wujiannpc]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_20]]},["fb205_27"]={["down"]=[[fb205_28]],["dsc"]=[[中央广场南面的大街，往北便是中央广场。果农们吆喝贩卖着干果，不时相互闲聊几句今年种下的果种。几个孩童也不知是从哪里寻了一个破窑罐，找了一把枯木枝，有模有样的投起壶来。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_27]],["name"]=[[平安南街]],["permission"]=1,["right"]=[[fb205_46]],["role1"]=[[changzhujumin4]],["role2"]=[[changzhujumin23]],["role3"]=[[22qxnpc10a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_24]]},["fb205_28"]={["down"]=[[fb205_29]],["dsc"]=[[中央广场南面的大街，往北便是中央广场。果农们吆喝贩卖着干果，不时相互闲聊几句今年种下的果种。几个孩童也不知是从哪里寻了一个破窑罐，找了一把枯木枝，有模有样的投起壶来。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_28]],["item1"]=[[22qxwp06]],["name"]=[[平安南街]],["permission"]=1,["role1"]=[[22qxnpc01a]],["role2"]=[[22qxnpc02a]],["role3"]=[[22qxnpc03a]],["role4"]=[[22qxnpc04a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_27]]},["fb205_29"]={["dsc"]=[[一片清澈的湖水，四面环柳，湖中画舫往来，四周挂着彩灯，将湖水映照得犹如白昼。湖畔每棵树上都挂着小小的彩灯，此时都在随风摇荡着，一片火光粼粼，煞是好看。湖中的画舫隐隐传开谈笑声。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_29]],["item1"]=[[fbqztrigger02]],["left"]=[[fb205_51]],["name"]=[[流樱湖]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb205_28]]},["fb205_30"]={["dsc"]=[[二层高的酒楼。前几日来了几个东洋客商，掌柜的一时高兴买了些罕见的食材，所以门口木牌上写菜名都是你从未听过的。一伙侠客相约至此比酒，吆喝着小二将一坛坛上好的女儿红抱了上来，旁边两个妇人不知道为何吵了起来，整个饭馆内热闹非凡。]],["id"]=[[fb205_30]],["item1"]=[[changzhubaishe20]],["left"]=[[fb205_10]],["name"]=[[菜来饭馆]],["permission"]=2,["right"]=[[fb205_31]],["stepMusic"]=[[jiaobu]]},["fb205_31"]={["dsc"]=[[酒馆的后厨房，大厨们正忙着烧菜，一旁的碗筷堆积着，无人清洗。]],["id"]=[[fb205_31]],["left"]=[[fb205_30]],["name"]=[[后厨]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb205_32"]={["dsc"]=[[这里是浮云寺的后寺，寺院正中有一个几人抱的大树。]],["id"]=[[fb205_32]],["left"]=[[fb205_22]],["name"]=[[后寺]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb205_33"]={["down"]=[[fb205_36]],["dsc"]=[[一条村子郊外的土路。曲曲折折，好在还算宽敞。几个孩童蹲在小溪边，微卷着手袖，试图将溪中的鱼儿捞起，却溅了一身的水花。旁边务农的老农夫正坐在路边，喝着碗中的清水。]],["id"]=[[fb205_33]],["name"]=[[村外土路]],["permission"]=2,["right"]=[[fb205_34]],["role1"]=[[changzhujumin9]],["stepMusic"]=[[jiaobu]]},["fb205_34"]={["dsc"]=[[一条村子郊外的土路。曲曲折折，好在还算宽敞。几个孩童蹲在小溪边，微卷着手袖，试图将溪中的鱼儿捞起，却溅了一身的水花。旁边务农的老农夫正坐在路边，喝着碗中的清水。]],["id"]=[[fb205_34]],["item1"]=[[changzhubaishe9]],["left"]=[[fb205_33]],["name"]=[[村外土路]],["permission"]=2,["right"]=[[fb205_35]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_50]]},["fb205_35"]={["dsc"]=[[平安小镇之外的一处不高的小山。几只野兔正在觅食，听得草丛中的脚步声匆忙窜入了洞中，不知去向。山亭外的小树绿荫盎然，也不知是谁在树上挂上了红布条，上面写着“平安顺遂”四个字。]],["id"]=[[fb205_35]],["item1"]=[[changzhubaishe24]],["left"]=[[fb205_34]],["name"]=[[平丘山]],["permission"]=2,["rightUp"]=[[fb205_54]],["stepMusic"]=[[jiaobu]]},["fb205_36"]={["down"]=[[fb205_38]],["dsc"]=[[村子外一片开阔的平地，后来被用作打谷场。几个簸箕斜躺在地上，一个农妇正喂食着家中的牲畜，一侧的木制篱笆上新藤初爬，偶能看到几只麻雀飞来。]],["id"]=[[fb205_36]],["item1"]=[[cfitem39]],["item2"]=[[changzhubaishe25]],["name"]=[[打谷场]],["permission"]=2,["right"]=[[fb205_37]],["role1"]=[[changzhujumin37a]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_33]]},["fb205_37"]={["dsc"]=[[平安小镇农户共同挖掘的灌溉井。井口约有两尺，深不见底，平日为防止牲畜掉落，都盖上了石板。井的边缘设置有引流灌溉的竹管，一直延伸到农田。]],["id"]=[[fb205_37]],["item1"]=[[2020bafangsj1]],["left"]=[[fb205_36]],["leftDown"]=[[fb205_38]],["name"]=[[灌溉井]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb205_38"]={["down"]=[[fb205_40]],["dsc"]=[[平安小镇外的一条碎石路，上面铺满了细碎的石子，踩上去咯吱作响。]],["id"]=[[fb205_38]],["item1"]=[[changzhubaishe1]],["name"]=[[碎石小路]],["permission"]=2,["right"]=[[fb205_39]],["rightUp"]=[[fb205_37]],["role1"]=[[changzhujumin12]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_36]]},["fb205_39"]={["dsc"]=[[平安小镇外的一大片宽阔的农田。田间五谷葱翠，偶有几只蚂蚱立于其上，农人们脱下鞋袜坐于田埂，端着一碗白水一饮而尽。几个孩童手拿小竹篓在田里来回奔跑，惊起了停在田间的飞鸟。一个侠客正拉着位老汉问路，旁边的骏马上还驮着几把长剑。]],["id"]=[[fb205_39]],["item1"]=[[2020bafangfl1]],["left"]=[[fb205_38]],["name"]=[[农田]],["permission"]=2,["right"]=[[fb205_45]],["role1"]=[[20bafanghsg1]],["role2"]=[[20ldjhdnpc2c]],["stepMusic"]=[[jiaobu]]},["fb205_40"]={["down"]=[[fb205_42]],["dsc"]=[[平安小镇外的一条碎石路，上面铺满了细碎的石子，踩上去咯吱作响。]],["id"]=[[fb205_40]],["item1"]=[[25mask02wp]],["name"]=[[碎石路]],["permission"]=2,["right"]=[[fb205_41]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_38]]},["fb205_41"]={["dsc"]=[[平安小镇外的一条碎石路，上面铺满了细碎的石子，踩上去咯吱作响。]],["id"]=[[fb205_41]],["left"]=[[fb205_40]],["name"]=[[碎石路]],["permission"]=2,["right"]=[[fb205_44]],["role1"]=[[changzhujumin30]],["stepMusic"]=[[jiaobu]]},["fb205_42"]={["down"]=[[fb205_43]],["dsc"]=[[这里是平安小镇的陵园，小镇的老人在过世之后都会葬在此处，也有一些江湖人士殉葬于此，每逢清明时节都有不少人来此祭奠。]],["id"]=[[fb205_42]],["item1"]=[[changzhubaishe28]],["item2"]=[[changzhubaishe27]],["name"]=[[平安陵园]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb205_40]]},["fb205_43"]={["dsc"]=[[这里是平安小镇的陵园，小镇的老人在过世之后都会葬在此处，也有一些江湖人士殉葬于此，每逢清明时节都有不少人来此祭奠。]],["id"]=[[fb205_43]],["item1"]=[[changzhubaishe29]],["name"]=[[平安陵园]],["permission"]=2,["role1"]=[[changzhujumin10]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_42]]},["fb205_44"]={["dsc"]=[[这里是平安小镇的西村口，再往西就出小镇了，往东可以前往平安小镇。]],["id"]=[[fb205_44]],["item1"]=[[changzhubaishe8]],["left"]=[[fb205_41]],["name"]=[[小镇西口]],["permission"]=1,["right"]=[[fb205_15]],["role1"]=[[zhouhuodongwjl]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_14]]},["fb205_45"]={["dsc"]=[[农夫为了喂养鸡鸭而搭建的石头房屋。只是简单地用大块石头累成，再搭上一个茅草屋顶。石屋之内鸡鸭的气味浓郁，不时传来鸡鸭的声音。一名农夫正靠在门前打盹。]],["id"]=[[fb205_45]],["left"]=[[fb205_39]],["name"]=[[石屋]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb205_46"]={["dsc"]=[[平安小镇的一家澡堂。澡堂之内被隔开成多个小间，小间之内都设置有木桶、木盆、皂角、沐巾等一应沐浴用物品。由于此处以药浴闻名，不少外乡人都慕名而来，澡堂之内时常人满为患。]],["id"]=[[fb205_46]],["item1"]=[[changzhubaishe5]],["left"]=[[fb205_27]],["name"]=[[澡堂]],["permission"]=2,["role1"]=[[changzhujumin14]],["stepMusic"]=[[jiaobu]]},["fb205_47"]={["down"]=[[fb205_01]],["dsc"]=[[平安江一旁的一个码头，平日里作为商贸来往的场所。]],["id"]=[[fb205_47]],["item1"]=[[changzhubaishe21]],["name"]=[[码头]],["permission"]=2,["role1"]=[[changzhujumin28]],["role2"]=[[22qxnpc06a]],["role3"]=[[21xiangnangnpc]],["role4"]=[[22xiangnangnpc]],["stepMusic"]=[[jiaobu]]},["fb205_48"]={["dsc"]=[[车行是一间三进的隔间房，门口有一个巨大的柜台和几张四四方方的矮桌，中间的屋子里是账房专门用来算账的地方，笔墨俱全；最后的隔间有一道小门，里头用于存放账本和银两，平日里都用锁锁上。]],["id"]=[[fb205_48]],["left"]=[[fb205_49]],["name"]=[[车行]],["permission"]=2,["role1"]=[[51npc01f]],["stepMusic"]=[[jiaobu]],["up"]=[[fb205_15]]},["fb205_49"]={["dsc"]=[[新造的马房，门口放着两个干净的水桶，角落里堆放着许多的干草，一排排有序的围栏专门用来绑缚马匹。左右两面的墙壁上，一侧挂着各式的马鞍，一侧则是长短不一的马鞭。]],["id"]=[[fb205_49]],["item1"]=[[jmnpc1]],["name"]=[[马房]],["permission"]=2,["right"]=[[fb205_48]],["stepMusic"]=[[jiaobu]]},["fb205_50"]={["down"]=[[fb205_34]],["dsc"]=[[一座再寻常不过的简陋木屋，墙角斜放着两把锄头和一柄长剑，靠床的木窗下放着两个大木箱，上面一盏烛灯结蜡，除此之外再无其他。]],["id"]=[[fb205_50]],["name"]=[[木屋]],["permission"]=2,["role1"]=[[20xcnpc48b]],["role2"]=[[mengjingwxzh1]],["stepMusic"]=[[jiaobu]]},["fb205_51"]={["dsc"]=[[湖畔树上都挂着小小的彩灯，湖风袭来时随之摇摆，层层涟漪下锦鲤游窜。岸边的青石道上人来人往，甚是热闹。]],["id"]=[[fb205_51]],["name"]=[[湖畔]],["permission"]=2,["right"]=[[fb205_29]],["role1"]=[[21znqnpc01a]],["role2"]=[[22zhounianqingsc]],["role3"]=[[24masknpc]],["stepMusic"]=[[jiaobu]]},["fb205_52"]={["dsc"]=[[门匾上大大写着“马宅”两个字，旁边两个大红灯笼略有些俗气，前头一个巨大的马厩。既像是寻常人家所居之地，又像是后院马房。时常有人牵着马往这头走，误认成驿站车行。]],["id"]=[[fb205_52]],["left"]=[[fb205_06]],["name"]=[[马宅]],["permission"]=2,["role1"]=[[dyrwnpc1]],["role2"]=[[dyrwnpc2]],["stepMusic"]=[[jiaobu]]},["fb205_53"]={["dsc"]=[[一间新建的篱笆小院，院前种了一棵桂花树，树下倚着锄头、箩筐，周围生满野花。院内一间普通茅屋，屋前挂有高粱、玉米，看起来十分古朴。院主人似乎刚刚搬来此地不久。]],["id"]=[[fb205_53]],["name"]=[[篱笆小院]],["permission"]=2,["right"]=[[fb205_02]],["stepMusic"]=[[jiaobu]]},["fb205_54"]={["dsc"]=[[平安小镇外的一处温泉，水汽氤氲，温暖无比。泉内设了数个小隔间，隔间门上挂着火红的灯笼。]],["fightBackground"]=[[森林内]],["id"]=[[fb205_54]],["leftDown"]=[[fb205_35]],["name"]=[[温泉]],["permission"]=2,["stepMusic"]=[[jiaobu]]},["fb205_55"]={["down"]=[[fb205_05]],["dsc"]=[[北内大街一旁的小巷，里面深邃幽暗堆放着不少杂物，很少有人进去。]],["fightBackground"]=[[城镇室外]],["id"]=[[fb205_55]],["name"]=[[北巷口]],["permission"]=2,["stepMusic"]=[[jiaobu]]}}00000000000000